import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.BvlN9b-o.js";const f=JSON.parse('{"title":"Public Errors and Troubleshooting","description":"","frontmatter":{"docLocale":"en","counterpart":"/reference/errors","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"en/reference/errors.md","filePath":"en/reference/errors.md"}'),o={name:"en/reference/errors.md"};function s(c,e,n,i,l,b){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="public-errors-and-troubleshooting" tabindex="-1">Public Errors and Troubleshooting <a class="header-anchor" href="#public-errors-and-troubleshooting" aria-label="Permalink to &quot;Public Errors and Troubleshooting&quot;">​</a></h1><p>Choose recovery by HTTP status, then branch on stable <code>error.code</code>. <a href="./api#schema-ApiErrorResponse">ApiErrorResponse</a> and <a href="./api#schema-ApiError">ApiError</a> define the generated structure; business code should not maintain another DTO. <code>error.message</code> is public explanatory text, not a client branch key. Current <code>public_error</code> returns empty <code>details</code>; do not expect database exceptions or form field errors.</p><h2 id="request-correlation" tabindex="-1">Request Correlation <a class="header-anchor" href="#request-correlation" aria-label="Permalink to &quot;Request Correlation&quot;">​</a></h2><p>Core <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer">request_context</a> generates a new <code>RequestId</code> per request and returns <code>x-request-id</code>. Error JSON uses that same value in <code>error.request_id</code>. Client-supplied request ids are not directly trusted. Record method, route, status, stable code and request_id, then correlate through Logs and tracing. Exclude Cookies, Authorization, request bodies and signed URLs.</p><p>With the local API running, observe a safe failed request:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/does-not-exist</span></span></code></pre></div><p>Expect <code>404</code>, <code>http.not_found</code>, <code>x-request-id</code> and a matching JSON request_id. HTML or a proxy error means the response has not reached Core&#39;s error boundary; check proxy targets and paths first.</p><h2 id="http-and-authentication" tabindex="-1">HTTP and Authentication <a class="header-anchor" href="#http-and-authentication" aria-label="Permalink to &quot;HTTP and Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Stable code / source</th><th>Recovery</th></tr></thead><tbody><tr><td>400</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_json</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_query</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.invalid_path</code></a></td><td>Correct JSON, query or path types; do not retry unchanged input</td></tr><tr><td>404 / 405</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.not_found</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.method_not_allowed</code></a></td><td>Check API assembly, paths and HTTP methods against current OpenAPI</td></tr><tr><td>408 / 413</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.body_timeout</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>http.payload_too_large</code></a></td><td>Check upload speed or reduce the body; use Files for binary content instead of increasing JSON budgets</td></tr><tr><td>401</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.unauthorized</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.invalid_credentials</code></a></td><td>Log in again or provide an active credential; Bearer never falls back to Cookie</td></tr><tr><td>403</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.origin</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.csrf</code></a></td><td>Check APP_ORIGIN; refresh Session and use its current csrf_token for mutations</td></tr><tr><td>403</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/api_keys/authentication.rs" target="_blank" rel="noreferrer"><code>api_keys.scope_forbidden</code></a></td><td>Obtain the required scope; business rules still check resource access</td></tr><tr><td>409</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.email_exists</code></a></td><td>Use the existing account or choose another registration email</td></tr><tr><td>429</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>rate_limit.exceeded</code></a></td><td>Honor <code>Retry-After</code> with bounded backoff; avoid concurrent retry loops</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/lib.rs" target="_blank" rel="noreferrer"><code>database.unavailable</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.unavailable</code></a></td><td>Check database, migrations and connection budgets; retain request_id and bound retries</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>auth.session_unavailable</code></a></td><td>Account creation may already have committed; log in instead of registering again</td></tr></tbody></table><h2 id="files-and-jobs" tabindex="-1">Files and Jobs <a class="header-anchor" href="#files-and-jobs" aria-label="Permalink to &quot;Files and Jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Stable code / source</th><th>Recovery</th></tr></thead><tbody><tr><td>400 / 413</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.invalid_input</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.too_large</code></a></td><td>Correct filename, media type, size or SHA-256; generated configuration defines limits</td></tr><tr><td>404 / 410</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.not_found</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_expired</code></a></td><td>Check business ownership for the former; start a new upload session for the latter</td></tr><tr><td>409</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_missing</code></a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_changed</code></a></td><td>Upload actual bytes first; changed content requires completion verification again</td></tr><tr><td>422</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.upload_rejected</code></a></td><td>Start a new upload session and recalculate size/hash</td></tr><tr><td>503</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>files.unavailable</code></a></td><td>Check matching API/Worker storage settings, bucket and service availability; use bounded retries</td></tr></tbody></table><p>Job errors are separate from HTTP statuses. Handlers return <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">JobError</a>: <code>Permanent</code> ends the current batch, <code>Transient</code> retries within budget and <code>LostLease</code> prevents publication. Job details and attempt records expose last_error. The Recovery guide explains when administrators start a new batch. Retain job_id, correlation_id and the original request_id.</p><h2 id="your-business-errors" tabindex="-1">Your Business Errors <a class="header-anchor" href="#your-business-errors" aria-label="Permalink to &quot;Your Business Errors&quot;">​</a></h2><p>Define Domain failures first, then map them through <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>public_error</code></a> to statuses and stable codes with a business prefix. Transaction failures roll back. Payload mismatch for an idempotency key and stale-version mutations should return <code>409</code>, preserving existing data. Add public failure behavior checks for these branches; see <a href="./../testing/feedback-loop">Testing feedback loop</a>.</p><p>Startup <code>ConfigError</code> occurs before HTTP exists. Check the named variable against <a href="./configuration-sources">Configuration sources</a>. For API readiness failure, verify migrations first. For a Worker that does not claim jobs, check kind registration and running state before leases and attempt budgets.</p><p>The reference domain&#39;s <a href="./../tutorials/observability">Logs and tracing guide</a> and <a href="./../tutorials/job-recovery">Job recovery guide</a> provide complete request/job investigation flows. Removing knowledge leaves the Core error reference and public source entries available.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/reference/errors.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',18)])])}const h=t(o,[["render",s]]);export{f as __pageData,h as default};
